#!/bin/bash
# GENERATED by configs/ipt_spt/generate_arm_configs.py from configs/ipt_spt/arms.yaml and the provenance of the corpora. Do not edit.
# Submits the 4 jobs that train the ipt arm (ps_ipt_nano_300b), behind a gate job that is held. Each job resumes from the
# save of the one before, and each exits 1400 minutes after it starts. Link 1 runs ipt_pretrain.yaml, and the later links run
# ipt_resume.yaml, which ends a link that finds no save. No job starts until the gate is released:
#   scontrol release <gate job id>
# Usage: FROZEN=<frozen copy of the committed code> bash ipt_launch.sh
set -euo pipefail
: "${FROZEN:?FROZEN must name the frozen copy of the committed code}"
test -f "$FROZEN/REVISION"
cd "$FROZEN"
export TMPDIR=/tmp
export ISAMBARD_ENV_OVERRIDES="$FROZEN/configs/quickstart/nemotron_nano_quickstart_pretrain.env"
GATE=$(isambard_sbatch --hold --nodes=1 --time=00:05:00 --job-name=ps_ipt_nano_300b-gate --wrap true | grep -o '[0-9]*$')
echo "gate job $GATE is held; release it with: scontrol release $GATE"
for link in $(seq 1 4); do
    dependency=singleton
    config="$FROZEN/configs/ipt_spt/ipt_resume.yaml"
    if [ "$link" -eq 1 ]; then dependency="afterok:$GATE,singleton"; config="$FROZEN/configs/ipt_spt/ipt_pretrain.yaml"; fi
    isambard_sbatch --nodes=32 --time=23:59:00 --job-name=ps_ipt_nano_300b --dependency="$dependency" \
        pipeline_training_submit.sbatch "$config" nano pretrain --disable-ft
done
